import json

with open('incidents.json') as f:
    incidents = json.load(f)

total = len(incidents)
sev1_ids = []

for inc in incidents:
    if inc['impact'] == 'high' or inc['users_affected'] >= 1000 or inc['duration_min'] >= 240:
        sev1_ids.append(inc['id'])

print('Total:', total)
print('Sev-1 count:', len(sev1_ids))
print('Rate:', round(len(sev1_ids)/total*100, 2), '%')
print('Sev-1 IDs:', sorted(sev1_ids))

# Show each Sev-1 and why
for inc in incidents:
    if inc['id'] in sev1_ids:
        reasons = []
        if inc['impact'] == 'high': reasons.append('impact=high')
        if inc['users_affected'] >= 1000: reasons.append(f'users={inc[\"users_affected\"]}')
        if inc['duration_min'] >= 240: reasons.append(f'duration={inc[\"duration_min\"]}')
        print(f\"  {inc['id']}: {', '.join(reasons)}\")
